CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS instructors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institutional_id TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_number TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS courses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, instructor_id UUID NOT NULL REFERENCES instructors(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrollments (course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, PRIMARY KEY (course_id, student_id));
CREATE TABLE IF NOT EXISTS attendance_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_id UUID NOT NULL REFERENCES courses(id), opened_by UUID NOT NULL REFERENCES instructors(id), mode TEXT NOT NULL CHECK (mode IN ('lab','lecture')), beacon_location GEOGRAPHY(POINT,4326) NOT NULL, allowed_cidr CIDR NOT NULL, starts_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL, closed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS attendance_sessions_location_idx ON attendance_sessions USING GIST (beacon_location);
CREATE TABLE IF NOT EXISTS attendance_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID NOT NULL REFERENCES attendance_sessions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id), token_hash TEXT UNIQUE NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ, UNIQUE (session_id, student_id));
CREATE TABLE IF NOT EXISTS attendance_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID NOT NULL REFERENCES attendance_sessions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id), status TEXT NOT NULL CHECK (status IN ('present','absent','rejected','overridden')), verified_at TIMESTAMPTZ, verification_reason TEXT, overridden_by UUID REFERENCES instructors(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (session_id, student_id));
